// Create a new document and validate non-null postcondition
QLJS_Web_Demo_Document* document = qljs_web_demo_create_document();
if (!document) { FUZZ_BAIL(); }

// Track lifetime and config association state for precondition checks in other stubs
FUZZ_SET_ATTR_INT(document, "destroyed", 0);
FUZZ_SET_ATTR_INT(document, "has_config", 0);
// document is returned as an output for reuse by later stubs

// Enforce preconditions: document must have been created and not yet destroyed
int was_destroyed = FUZZ_GET_ATTR_INT(document, "destroyed");
if (was_destroyed) { FUZZ_BAIL(); }

// Mark destroyed before calling to avoid double-destroy via reentrancy in fuzz scheduling
FUZZ_SET_ATTR_INT(document, "destroyed", 1);

// Destroy the document; it must not be used after this point
qljs_web_demo_destroy_document(document);
// No outputs: runtime drops ownership to avoid use-after-free

// Precondition: document must be valid (created and not destroyed)
if (FUZZ_GET_ATTR_INT(document, "destroyed")) { FUZZ_BAIL(); }

// Generate a UTF-8 byte buffer; ensure size <= 2048 for performance
std::string text = FUZZ_PARAM_STR();
if (text.size() > 2048) { text.resize(2048); }
// API requires non-null pointer even if size==0; FUZZ_PARAM_STR guarantees size>=1
const void* buf = static_cast<const void*>(text.data());
size_t len = text.size();

// Set the text; contents are internally copied by the API
qljs_web_demo_set_text(document, buf, len);

// Keep document alive for further operations

// Preconditions: both documents valid and distinct when non-null, and not destroyed
if (FUZZ_GET_ATTR_INT(js_document, "destroyed")) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(config_document, "destroyed")) { FUZZ_BAIL(); }
// Do not allow setting a document as its own config
if (js_document == config_document) { FUZZ_BAIL(); }

// Randomly choose to associate the given config or clear the config
bool use_config = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
QLJS_Web_Demo_Document* cfg = use_config ? config_document : nullptr;
qljs_web_demo_set_config(js_document, cfg);

// Track whether a config is associated (cannot track its lifetime reliably here)
FUZZ_SET_ATTR_INT(js_document, "has_config", use_config ? 1 : 0);

// Both documents remain valid; return both as outputs

// Preconditions: document must be valid
if (FUZZ_GET_ATTR_INT(document, "destroyed")) { FUZZ_BAIL(); }

// Build a valid bitmask from known option bits
unsigned r = *FUZZ_PARAM(unsigned int);
unsigned mask = 0u;
if (r & 1u) { mask |= qljs_language_options_jsx_bit; }
if (r & 2u) { mask |= qljs_language_options_typescript_bit; }
if (r & 4u) { mask |= qljs_language_options_config_json_bit; }

qljs_web_demo_set_language_options(document, static_cast<QLJS_Language_Options>(mask));

// Track for potential downstream validation
FUZZ_SET_ATTR_INT(document, "lang_options", static_cast<int>(mask));

// Preconditions: document must be valid
if (FUZZ_GET_ATTR_INT(document, "destroyed")) { FUZZ_BAIL(); }

// Try to choose a supported locale sometimes; otherwise use a fuzzed string
const char* chosen_locale = nullptr;
const char* const* locales = qljs_list_locales();
if (locales) {
    // Pick an index in [0,3] and advance if possible, else fall back
    unsigned idx = (*FUZZ_PARAM(unsigned int)) % 4u;
    const char* const* p = locales;
    while (idx > 0 && p && *p) { ++p; --idx; }
    if (p && *p && (*p)[0] != '\0') { chosen_locale = *p; }
}

std::string fuzz_locale;
if (!chosen_locale) {
    fuzz_locale = FUZZ_PARAM_STR();
    // Ensure null-terminated C string for API
    chosen_locale = fuzz_locale.c_str();
}

qljs_web_demo_set_locale(document, chosen_locale);
// Document remains valid and is returned as output

// Preconditions: document must be valid and any associated config must not have been destroyed
if (FUZZ_GET_ATTR_INT(document, "destroyed")) { FUZZ_BAIL(); }

// Lint and validate non-null diagnostics pointer
const QLJS_Web_Demo_Diagnostic* diags = qljs_web_demo_lint(document);
if (!diags) { FUZZ_BAIL(); }

// Iterate a bounded number of diagnostics to exercise array termination logic
for (int i = 0; i < 16; ++i) {
    const QLJS_Web_Demo_Diagnostic& d = diags[i];
    if (d.message == nullptr) { break; }
    // Property: severity must be one of the defined enum values
    int sev_ok = (d.severity == qljs_severity_error) || (d.severity == qljs_severity_warning);
    FUZZ_ASSERT(sev_ok, "Unexpected diagnostic severity value");
    // Do not retain pointers; diagnostics lifetime ends on next lint/destroy
}

// Document remains valid and is returned as output

// Get the locale list and validate basic postconditions
const char* const* locales = qljs_list_locales();
if (!locales) { FUZZ_BAIL(); }

// Must contain at least one non-empty string and be null-terminated
bool saw_non_empty = false;
bool saw_terminator = false;
for (int i = 0; i < 64; ++i) { // Bound to keep fuzz runtime fast
    const char* s = locales[i];
    if (!s) { saw_terminator = true; break; }
    if (s[0] != '\0') { saw_non_empty = true; }
}
FUZZ_ASSERT(saw_non_empty, "Locale list did not contain a non-empty string");
FUZZ_ASSERT(saw_terminator, "Locale list not null-terminated within limit");

