import random
import string
from typing import List

# Generator for UTF-8 text buffers suitable for qljs_web_demo_set_text
# Produces valid, interesting JS/TS/JSX/config JSON content with Unicode spice.

MAX_TOTAL = 2048

JSX_TAGS = ['div', 'span', 'img', 'Button', 'Component', 'MyComp']

LOCALES = ['en', 'en-US', 'fr', 'de', 'es', 'ja', 'zh-CN']

UNICODE_IDENT_PARTS = [
    'α','β','γ','δ','λ','π','σ','τ','φ','χ','ψ','Ω',
    'А','Б','В','Г','Д','Ж','З','И','Й','К',
    '字','変','数','名','漢','字',
    '😀','😺','🧪','🧵','⚙',
]

COMBINING = ['\u0301','\u0300','\u0308','\u0327','\u20DD']

WHITES = [' ', '\t', '\u00A0', '\u2003']


def rnd(r: random.Random, seq):
    return r.choice(seq)


def maybe(r: random.Random, p: float) -> bool:
    return r.random() < p


def make_js_snippet(r: random.Random) -> str:
    parts = []
    if maybe(r, 0.5):
        parts.append("// simple JS snippet\n")
    if maybe(r, 0.3):
        parts.append("'use strict';\n")
    for _ in range(r.randint(1, 4)):
        kw = rnd(r, ['let', 'const', 'var'])
        name = make_identifier(r)
        expr = make_js_expr(r)
        parts.append(kw + " " + name + " = " + expr + ";\n")
    if maybe(r, 0.7):
        fname = make_identifier(r)
        params = ", ".join(make_identifier(r) for _ in range(r.randint(0, 3)))
        body_lines = []
        for i in range(r.randint(1, 3)):
            if i == 0:
                body_lines.append("return " + make_js_expr(r) + ";")
            else:
                body_lines.append(rnd(r, ['let','const']) + " " + make_identifier(r) + " = " + make_js_expr(r) + ";")
        body = "\n  " + "\n  ".join(body_lines) + "\n"
        # Avoid f-strings with braces: concatenate explicitly
        parts.append("function " + fname + "(" + params + ") {" + body + "}\n")
    if maybe(r, 0.4):
        cname = make_identifier(r)
        ext = (" extends " + make_identifier(r)) if maybe(r, 0.5) else ""
        parts.append("class " + cname + ext + " {\n  constructor() { this.x = " + str(r.randint(0,9)) + "; }\n  m(a) { return a ?? this.x; }\n}\n")
    if maybe(r, 0.3):
        parts.append("export const E = 1;\n")
    if maybe(r, 0.3):
        parts.append("import x from 'mod';\n")
    parts.append("const re = /a+b?\\d*/gi;\n")
    parts.append("const t = `line1\\n${1+2}`;\n")
    return "".join(parts)


def make_ts_snippet(r: random.Random) -> str:
    parts = []
    if maybe(r, 0.7):
        T = make_identifier(r)
        parts.append("type " + T + " = " + rnd(r, ['string','number','boolean','any','unknown','never','void','bigint','symbol']) + " | { a: number; b?: string };\n")
    if maybe(r, 0.7):
        I = make_identifier(r)
        parts.append("interface " + I + " { x: number; y?: string; }\n")
    if maybe(r, 0.6):
        G = make_identifier(r)
        parts.append("function id<" + G + ">(" + make_identifier(r) + ": " + G + "): " + G + " { return arguments[0] as " + G + "; }\n")
    if maybe(r, 0.4):
        E = make_identifier(r)
        parts.append("enum " + E + " { A = 1, B, C = 4 }\n")
    parts.append("const n: number = 42 as number;\n")
    parts.append("declare const ext: any;\n")
    return "".join(parts)


def make_jsx_snippet(r: random.Random) -> str:
    props = []
    if maybe(r, 0.7):
        props.append("className=\"" + rnd(r, ['x','btn','container']) + "\"")
    if maybe(r, 0.6):
        props.append("onClick={() => 1}")
    if maybe(r, 0.5):
        props.append("data-id={42}")
    tag = rnd(r, JSX_TAGS)
    inner = rnd(r, ["Hello", "{1+2}", "<span>Child</span>", "{[1,2,3].map(x=>x)}"]) 
    open_tag = "<" + tag + " " + " ".join(props) + ">" + inner + "</" + tag + ">"
    return open_tag + "\n"


def make_config_json(r: random.Random) -> str:
    cfg = {
        "extends": rnd(r, ["recommended", "strict", "none"]),
        "rules": {
            "no-undef": rnd(r, ["off", "warn", "error"]),
            "no-unused-vars": rnd(r, ["off", "warn", "error"]),
            "eqeqeq": rnd(r, ["off", "warn", "error"]),
        },
        "env": {
            "browser": maybe(r, 0.5),
            "node": maybe(r, 0.5)
        },
        "parserOptions": {
            "jsx": maybe(r, 0.5),
            "typescript": maybe(r, 0.5)
        },
        "locale": rnd(r, LOCALES)
    }
    def dumps(obj, indent=0):
        sp = '  ' * indent
        if isinstance(obj, dict):
            items = []
            for k, v in obj.items():
                items.append(sp + "  \"" + str(k).replace('"','\\"') + "\": " + dumps(v, indent+1))
            return '{\n' + ',\n'.join(items) + "\n" + sp + "}"
        if isinstance(obj, bool):
            return 'true' if obj else 'false'
        if isinstance(obj, str):
            return '"' + obj.replace('"','\\"') + '"'
        if isinstance(obj, (int, float)):
            return str(obj)
        return 'null'
    return dumps(cfg) + "\n"


def make_identifier(r: random.Random) -> str:
    base = rnd(r, ['id','name','value','αβ','данные','変数','emoji'])
    if maybe(r, 0.6):
        base += rnd(r, UNICODE_IDENT_PARTS)
    if maybe(r, 0.4):
        base += rnd(r, COMBINING)
    if maybe(r, 0.3):
        base = base + rnd(r, ['_','$', '＄']) + str(r.randint(0,9))
    return base


def make_js_expr(r: random.Random) -> str:
    def number():
        return str(r.randint(-1000, 1000))
    def string_lit():
        return '"' + random_string(r, r.randint(0, 8)) + '"'
    def boolean():
        return 'true' if maybe(r, 0.5) else 'false'
    def array():
        return '[' + ','.join(str(r.randint(0,9)) for _ in range(r.randint(0, 5))) + ']'
    def obj():
        return '{x:' + str(r.randint(0,9)) + '}'
    def add():
        return '(' + str(r.randint(1,9)) + ' + ' + str(r.randint(1,9)) + ')'
    def regex():
        return '/' + random_regex_body(r) + '/' + rnd(r,['','g','i','m','gi','gm','im'])
    def tpl():
        inner = 'u-' + random_string(r, r.randint(0, 6))
        return '`' + inner + '`'
    choices = [number, string_lit, boolean, array, obj, add, regex, tpl]
    return rnd(r, choices)()


def random_regex_body(r: random.Random) -> str:
    atoms = ['a','b','c','\\d','\\w','\\s','.', '[a-z]', '[A-Z]', '[0-9]', '(?:ab)']
    body = ''.join(rnd(r, atoms) for _ in range(r.randint(1, 5)))
    if maybe(r, 0.5):
        body += rnd(r, ['+','*','?','{1,3}'])
    return body


def random_string(r: random.Random, n: int) -> str:
    alphabet = string.ascii_letters + string.digits + ' _-'
    return ''.join(r.choice(alphabet) for _ in range(n))


def add_unicode_spice(r: random.Random, s: str) -> str:
    prefix = ''
    if maybe(r, 0.2):
        prefix = '\ufeff'  # BOM
    lines = s.split('\n')
    out_lines = []
    for line in lines:
        if maybe(r, 0.3):
            line = rnd(r, WHITES) + line
        if maybe(r, 0.2):
            line = line + rnd(r, WHITES)
        if maybe(r, 0.2):
            line = line + rnd(r, ['😀','🚀','🧪'])
        if maybe(r, 0.1):
            line = '\u200F' + line  # RTL mark
        out_lines.append(line)
    sep = rnd(r, ['\n','\r\n','\r'])
    return prefix + sep.join(out_lines)


def build_document(r: random.Random) -> str:
    mode = rnd(r, ['js', 'ts', 'jsx', 'config', 'mixed'])
    parts: List[str] = []
    if mode == 'config':
        parts.append(make_config_json(r))
    else:
        if maybe(r, 0.4):
            parts.append("// locale: " + rnd(r, LOCALES) + "\n")
        if mode in ('js','mixed','jsx','ts') and maybe(r, 0.5):
            parts.append("/* multi-line\n   comment */\n")
        if mode in ('js','mixed'):
            parts.append(make_js_snippet(r))
        if mode in ('ts','mixed'):
            parts.append(make_ts_snippet(r))
        if mode in ('jsx','mixed'):
            parts.append(make_jsx_snippet(r))
        if maybe(r, 0.5):
            parts.append('let long_line = "' + 'x'*r.randint(30,120) + '";\n')
    doc = ''.join(parts)
    doc = add_unicode_spice(r, doc)
    return doc


def clamp_bytes(s: str) -> bytes:
    b = s.encode('utf-8', errors='strict')
    if len(b) > MAX_TOTAL:
        b = b[:MAX_TOTAL]
        s2 = b.decode('utf-8', errors='ignore')
        b = s2.encode('utf-8')
        if len(b) > MAX_TOTAL:
            b = b[:MAX_TOTAL]
    return b


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    chunks = []
    for _ in range(r.randint(1, 3)):
        chunks.append(build_document(r))
        if maybe(r, 0.5):
            chunks.append("\n// ---- \n\n")
    s = ''.join(chunks)
    if not s:
        s = "// empty\n"
    return clamp_bytes(s)
